AssistantMessageToolRequest(name='create', tool_call_id='function-call-98b094f5-c030-4805-876f-9339bc770274', arguments={'file_text': 'const { useState } = React;

const questions = [
  {
    id: 'q1',
    text: 'Which of these languages are memory-safe by default?',
    helpText: 'Memory safety prevents common bugs like buffer overflows and dangling pointers.',
    options: [
      { id: 'q1-rust', label: 'Rust' },
      { id: 'q1-java', label: 'Java' },
      { id: 'q1-python', label: 'Python' },
      { id: 'q1-cpp', label: 'C++' }
    ],
    answers: ['q1-rust', 'q1-java', 'q1-python']
  },
  {
    id: 'q2',
    text: 'Which of these languages were created or are primarily supported by Google?',
    options: [
      { id: 'q2-go', label: 'Go' },
      { id: 'q2-carbon', label: 'Carbon' },
      { id: 'q2-dart', label: 'Dart' },
      { id: 'q2-kotlin', label: 'Kotlin' }
    ],
    answers: ['q2-go', 'q2-carbon', 'q2-dart']
  },
  {
    id: 'q3',
    text: 'Which of these languages are commonly used for data science and machine learning?',
    options: [
      { id: 'q3-python', label: 'Python' },
      { id: 'q3-r', label: 'R' },
      { id: 'q3-julia', label: 'Julia' },
      { id: 'q3-scala', label: 'Scala' }
    ],
    answers: ['q3-python', 'q3-r', 'q3-julia', 'q3-scala']
  }
];

const Quiz = () => {
  const [selectedOptions, setSelectedOptions] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [score, setScore] = useState(0);

  const handleCheckboxChange = (questionId, optionId) => {
    setSelectedOptions(prev => {
      const currentSelected = prev[questionId] || [];
      if (currentSelected.includes(optionId)) {
        return { ...prev, [questionId]: currentSelected.filter(id => id !== optionId) };
      } else {
        return { ...prev, [questionId]: [...currentSelected, optionId] };
      }
    });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    let totalScore = 0;
    questions.forEach(q => {
      const userAnswers = selectedOptions[q.id] || [];
      const correctAnswers = q.answers;

      // Basic scoring: All correct must be selected, and no incorrect ones.
      const isCorrect = userAnswers.length === correctAnswers.length && 
                        userAnswers.every(val => correctAnswers.includes(val));
      if (isCorrect) totalScore++;
    });
    setScore(totalScore);
    setSubmitted(true);
  };

  return (
    <div className="quiz-container">
      <h1>Computer Languages Quiz</h1>
      <form onSubmit={handleSubmit}>
        {questions.map((q, index) => (
          <div key={q.id} className="form-field">
            <fieldset aria-describedby={q.helpText ? `${q.id}-help` : undefined}>
              <legend>{q.text}</legend>
              {q.helpText && (
                <div id={`${q.id}-help`} className="help-text">
                  {q.helpText}
                </div>
              )}
              <div className="options-group">
                {q.options.map(option => (
                  <div key={option.id} className="option-item">
                    <input
                      type="checkbox"
                      id={option.id}
                      checked={(selectedOptions[q.id] || []).includes(option.id)}
                      onChange={() => handleCheckboxChange(q.id, option.id)}
                    />
                    <label htmlFor={option.id}>{option.label}</label>
                  </div>
                ))}
              </div>
            </fieldset>
          </div>
        ))}
        <button type="submit" className="submit-btn">Submit Quiz</button>
      </form>
      {submitted && (
        <div className="results" role="alert">
          <h2>Your Results</h2>
          <p>You scored {score} out of {questions.length}!</p>
          <button onClick={() => {setSubmitted(false); setSelectedOptions({});}} className="submit-btn" style={{marginTop: '10px', backgroundColor: '#6c757d'}}>
            Try Again
          </button>
        </div>
      )}
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<Quiz />);
