                        <div className="results-box" role="alert">
                            <h2>Quiz Complete!</h2>
                            <p>You got <strong>{score}</strong> out of {questions.length} questions correct.</p>
                            <button 
                                className="retry-btn"
                                onClick={() => { setSubmitted(false); setSelected({}); }}
                            >
                                Try Again
                            </button>
                        </div>
                    )}
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<Quiz />);
    </script>
