    <a href="#main-content" class="skip-link">Skip to main content</a>
    <main id="root"></main>

    <script type="text/babel">
        const { useState } = React;

        const questions = [
            {
                id: 'q1',
                text: 'Which of these languages are memory-safe by default?',
                helpText: 'Memory safety prevents common bugs like buffer overflows and dangling pointers.',
                options: [
                    { id: 'q1-rust', label: 'Rust' },
                    { id: 'q1-java', label: 'Java' },
                    { id: 'q1-python', label: 'Python' },
                    { id: 'q1-cpp', label: 'C++' }
                ],
                answers: ['q1-rust', 'q1-java', 'q1-python']
            },
            {
                id: 'q2',
                text: 'Which of these languages were created or are primarily supported by Google?',
                options: [
                    { id: 'q2-go', label: 'Go' },
                    { id: 'q2-carbon', label: 'Carbon' },
                    { id: 'q2-dart', label: 'Dart' },
                    { id: 'q2-kotlin', label: 'Kotlin' }
                ],
                answers: ['q2-go', 'q2-carbon', 'q2-dart']
            },
            {
                id: 'q3',
                text: 'Which of these languages are commonly used for data science?',
                options: [
                    { id: 'q3-python', label: 'Python' },
                    { id: 'q3-r', label: 'R' },
                    { id: 'q3-julia', label: 'Julia' },
                    { id: 'q3-scala', label: 'Scala' }
                ],
                answers: ['q3-python', 'q3-r', 'q3-julia', 'q3-scala']
            }
        ];

        const Quiz = () => {
            const [selected, setSelected] = useState({});
            const [submitted, setSubmitted] = useState(false);
            const [score, setScore] = useState(0);

            const toggleOption = (qId, optId) => {
                setSelected(prev => {
                    const current = prev[qId] || [];
                    return {
                        ...prev,
                        [qId]: current.includes(optId)
                            ? current.filter(id => id !== optId)
                            : [...current, optId]
                    };
                });
            };

            const handleSubmit = (e) => {
                e.preventDefault();
                let correctCount = 0;
                questions.forEach(q => {
                    const userAnswers = selected[q.id] || [];
                    const isCorrect = userAnswers.length === q.answers.length && 
                                     userAnswers.every(id => q.answers.includes(id));
                    if (isCorrect) correctCount++;
                });
                setScore(correctCount);
                setSubmitted(true);
            };

            return (
                <div className="quiz-card">
                    <h1>Programming Quiz</h1>
                    <form onSubmit={handleSubmit}>
                        {questions.map((q, idx) => (
                            <div key={q.id} className="form-field">
                                <fieldset aria-describedby={q.helpText ? `${q.id}-help` : undefined}>
                                    <legend>{q.text}</legend>
                                    {q.helpText && (
                                        <div id={`${q.id}-help`} className="help-text">
                                            {q.helpText}
                                        </div>
                                    )}
                                    <div className="options-list">
                                        {q.options.map(opt => (
                                            <div key={opt.id} className="option-item">
                                                <input
                                                    type="checkbox"
                                                    id={opt.id}
                                                    checked={(selected[q.id] || []).includes(opt.id)}
                                                    onChange={() => toggleOption(q.id, opt.id)}
                                                />
                                                <label htmlFor={opt.id}>{opt.label}</label>
                                            </div>
                                        ))}
                                    </div>
                                </fieldset>
                            </div>
                        ))}
                        <button type="submit" className="submit-btn">
                            Submit Answers
                        </button>
                    </form>

                    {submitted && (
                        <div className="results-box" role="alert">
                            <h2>Quiz Complete!</h2>
                            <p>You got <strong>{score}</strong> out of {questions.length} questions correct.</p>
                            <button 
                                className="retry-btn"
                                onClick={() => { setSubmitted(false); setSelected({}); }}
                            >
                                Try Again
                            </button>
                        </div>
                    )}
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<Quiz />);
    </script>
